import sys
from datetime import datetime


def print_msg(*args, level="INFO", sep=" ", end="\n", file=None, with_time=True):
    """统一的打印函数。

    :param args:      要打印的内容，可传多个
    :param level:     日志级别，如 INFO / WARN / ERROR
    :param sep:       多个参数之间的分隔符
    :param end:       结尾字符
    :param file:      输出目标，默认标准输出；错误级别默认标准错误
    :param with_time: 是否在行首添加时间戳
    """
    out = file or (sys.stderr if level.upper() in ("ERROR", "WARN") else sys.stdout)
    prefix = f"[{datetime.now():%Y-%m-%d %H:%M:%S}][{level.upper()}] " if with_time else ""
    text = sep.join(str(a) for a in args)
    print(prefix + text, end=end, file=out, flush=True)


if __name__ == "__main__":
    print_msg("程序启动")
    print_msg("用户", "不存在", level="ERROR", sep=": ")
```

