/* 简单的格式化打印，统一走 stdout，失败时返回负数 */
int print_msg(const char *fmt, ...)
{
    va_list ap;
    int n;

    va_start(ap, fmt);
    n = vprintf(fmt, ap);
    va_end(ap);
    fflush(stdout);
    return n;
}
